INSERT INTO `landing_faqs` (`id`, `translations`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, '{\"fr\":{\"question\":\"Quelle est la dur\\u00e9e de l\'essai gratuit ?\",\"answer\":\"Chaque nouvel espace de travail b\\u00e9n\\u00e9ficie d\'un essai gratuit de 14 jours sur le plan Professionnel. Aucune carte de cr\\u00e9dit requise.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0645\\u062f\\u0629 \\u0627\\u0644\\u0641\\u062a\\u0631\\u0629 \\u0627\\u0644\\u062a\\u062c\\u0631\\u064a\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0645\\u062c\\u0627\\u0646\\u064a\\u0629\\u061f\",\"answer\":\"\\u064a\\u062d\\u0635\\u0644 \\u0643\\u0644 \\u0645\\u0633\\u0627\\u062d\\u0629 \\u0639\\u0645\\u0644 \\u062c\\u062f\\u064a\\u062f\\u0629 \\u0639\\u0644\\u0649 \\u0641\\u062a\\u0631\\u0629 \\u062a\\u062c\\u0631\\u064a\\u0628\\u064a\\u0629 \\u0645\\u062c\\u0627\\u0646\\u064a\\u0629 \\u0644\\u0645\\u062f\\u0629 14 \\u064a\\u0648\\u0645\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062e\\u0637\\u0629 \\u0627\\u0644\\u0627\\u062d\\u062a\\u0631\\u0627\\u0641\\u064a\\u0629. \\u0644\\u0627 \\u062d\\u0627\\u062c\\u0629 \\u0644\\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0626\\u062a\\u0645\\u0627\\u0646.\"},\"es\":{\"question\":\"\\u00bfCu\\u00e1nto dura la prueba gratuita?\",\"answer\":\"Cada nuevo espacio de trabajo incluye una prueba gratuita de 14 d\\u00edas en el plan Profesional. Sin tarjeta de cr\\u00e9dito.\"},\"hi\":{\"question\":\"\\u092e\\u0941\\u092b\\u094d\\u0924 \\u092a\\u0930\\u0940\\u0915\\u094d\\u0937\\u0923 \\u0915\\u093f\\u0924\\u0928\\u0947 \\u0926\\u093f\\u0928\\u094b\\u0902 \\u0915\\u093e \\u0939\\u0948?\",\"answer\":\"\\u0939\\u0930 \\u0928\\u090f \\u0915\\u093e\\u0930\\u094d\\u092f\\u0915\\u094d\\u0937\\u0947\\u0924\\u094d\\u0930 \\u092e\\u0947\\u0902 \\u092a\\u094d\\u0930\\u094b\\u092b\\u0947\\u0936\\u0928\\u0932 \\u092a\\u094d\\u0932\\u093e\\u0928 \\u092a\\u0930 14 \\u0926\\u093f\\u0928 \\u0915\\u093e \\u092e\\u0941\\u092b\\u094d\\u0924 \\u092a\\u0930\\u0940\\u0915\\u094d\\u0937\\u0923 \\u092e\\u093f\\u0932\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0915\\u094d\\u0930\\u0947\\u0921\\u093f\\u091f \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0915\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e \\u0928\\u0939\\u0940\\u0902\\u0964\"},\"bn\":{\"question\":\"\\u09ac\\u09bf\\u09a8\\u09be\\u09ae\\u09c2\\u09b2\\u09cd\\u09af\\u09c7 \\u099f\\u09cd\\u09b0\\u09be\\u09af\\u09bc\\u09be\\u09b2 \\u0995\\u09a4\\u09a6\\u09bf\\u09a8\\u09c7\\u09b0?\",\"answer\":\"\\u09aa\\u09cd\\u09b0\\u09a4\\u09bf\\u099f\\u09bf \\u09a8\\u09a4\\u09c1\\u09a8 \\u0993\\u09af\\u09bc\\u09be\\u09b0\\u09cd\\u0995\\u09b8\\u09cd\\u09aa\\u09c7\\u09b8 \\u09aa\\u09cd\\u09b0\\u09ab\\u09c7\\u09b6\\u09a8\\u09be\\u09b2 \\u09aa\\u09cd\\u09b2\\u09cd\\u09af\\u09be\\u09a8\\u09c7 14 \\u09a6\\u09bf\\u09a8\\u09c7\\u09b0 \\u09ac\\u09bf\\u09a8\\u09be\\u09ae\\u09c2\\u09b2\\u09cd\\u09af\\u09c7 \\u099f\\u09cd\\u09b0\\u09be\\u09af\\u09bc\\u09be\\u09b2 \\u09aa\\u09be\\u09af\\u09bc\\u0964 \\u0995\\u09cd\\u09b0\\u09c7\\u09a1\\u09bf\\u099f \\u0995\\u09be\\u09b0\\u09cd\\u09a1\\u09c7\\u09b0 \\u09aa\\u09cd\\u09b0\\u09af\\u09bc\\u09cb\\u099c\\u09a8 \\u09a8\\u09c7\\u0987\\u0964\"},\"tr\":{\"question\":\"\\u00dccretsiz deneme s\\u00fcresi ne kadar?\",\"answer\":\"Her yeni \\u00e7al\\u0131\\u015fma alan\\u0131, Professional planda 14 g\\u00fcnl\\u00fck \\u00fccretsiz deneme s\\u00fcresine sahiptir. Kredi kart\\u0131 gerekmez.\"},\"de\":{\"question\":\"Wie lange dauert die kostenlose Testversion?\",\"answer\":\"Jeder neue Arbeitsbereich erh\\u00e4lt eine 14-t\\u00e4gige kostenlose Testversion im Professional-Plan. Keine Kreditkarte erforderlich.\"},\"pt\":{\"question\":\"Quanto tempo dura o teste gratuito?\",\"answer\":\"Cada novo espa\\u00e7o de trabalho recebe um teste gratuito de 14 dias no plano Profissional. Sem necessidade de cart\\u00e3o de cr\\u00e9dito.\"}}', 'How long is the free trial?', 'Every new workspace comes with a 14-day free trial on the Professional plan. No credit card required.', 1, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15'),
(2, '{\"fr\":{\"question\":\"Puis-je g\\u00e9rer plusieurs entrep\\u00f4ts ?\",\"answer\":\"Oui. Tous les plans payants prennent en charge un nombre illimit\\u00e9 d\'entrep\\u00f4ts avec transferts de stock, ajustements et rapports par emplacement.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0645\\u0633\\u062a\\u0648\\u062f\\u0639\\u0627\\u062a \\u0645\\u062a\\u0639\\u062f\\u062f\\u0629\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645. \\u062a\\u062f\\u0639\\u0645 \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u062e\\u0637\\u0637 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0629 \\u0645\\u0633\\u062a\\u0648\\u062f\\u0639\\u0627\\u062a \\u063a\\u064a\\u0631 \\u0645\\u062d\\u062f\\u0648\\u062f\\u0629 \\u0645\\u0639 \\u0646\\u0642\\u0644 \\u0627\\u0644\\u0645\\u062e\\u0632\\u0648\\u0646 \\u0648\\u0627\\u0644\\u062a\\u0639\\u062f\\u064a\\u0644\\u0627\\u062a \\u0648\\u0627\\u0644\\u062a\\u0642\\u0627\\u0631\\u064a\\u0631 \\u062d\\u0633\\u0628 \\u0627\\u0644\\u0645\\u0648\\u0642\\u0639.\"},\"es\":{\"question\":\"\\u00bfPuedo gestionar m\\u00faltiples almacenes?\",\"answer\":\"S\\u00ed. Todos los planes de pago admiten almacenes ilimitados con transferencias de stock, ajustes e informes por ubicaci\\u00f3n.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0915\\u0908 \\u0917\\u094b\\u0926\\u093e\\u092e\\u094b\\u0902 \\u0915\\u094b \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902?\",\"answer\":\"\\u0939\\u093e\\u0902\\u0964 \\u0938\\u092d\\u0940 \\u092a\\u0947\\u0921 \\u092a\\u094d\\u0932\\u093e\\u0928 \\u0938\\u094d\\u091f\\u0949\\u0915 \\u091f\\u094d\\u0930\\u093e\\u0902\\u0938\\u092b\\u0930, \\u090f\\u0921\\u091c\\u0938\\u094d\\u091f\\u092e\\u0947\\u0902\\u091f \\u0914\\u0930 \\u092a\\u094d\\u0930\\u0924\\u093f-\\u0932\\u094b\\u0915\\u0947\\u0936\\u0928 \\u0930\\u093f\\u092a\\u094b\\u0930\\u094d\\u091f\\u093f\\u0902\\u0917 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0905\\u0938\\u0940\\u092e\\u093f\\u0924 \\u0917\\u094b\\u0926\\u093e\\u092e\\u094b\\u0902 \\u0915\\u093e \\u0938\\u092e\\u0930\\u094d\\u0925\\u0928 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"},\"bn\":{\"question\":\"\\u0986\\u09ae\\u09bf \\u0995\\u09bf \\u098f\\u0995\\u09be\\u09a7\\u09bf\\u0995 \\u0997\\u09c1\\u09a6\\u09be\\u09ae \\u09aa\\u09b0\\u09bf\\u099a\\u09be\\u09b2\\u09a8\\u09be \\u0995\\u09b0\\u09a4\\u09c7 \\u09aa\\u09be\\u09b0\\u09bf?\",\"answer\":\"\\u09b9\\u09cd\\u09af\\u09be\\u0981\\u0964 \\u09b8\\u09ae\\u09b8\\u09cd\\u09a4 \\u09aa\\u09c7\\u0987\\u09a1 \\u09aa\\u09cd\\u09b2\\u09cd\\u09af\\u09be\\u09a8 \\u09b8\\u09cd\\u099f\\u0995 \\u099f\\u09cd\\u09b0\\u09be\\u09a8\\u09cd\\u09b8\\u09ab\\u09be\\u09b0, \\u0985\\u09cd\\u09af\\u09be\\u09a1\\u099c\\u09be\\u09b8\\u09cd\\u099f\\u09ae\\u09c7\\u09a8\\u09cd\\u099f \\u098f\\u09ac\\u0982 \\u09aa\\u09cd\\u09b0\\u09a4\\u09bf-\\u09b2\\u09cb\\u0995\\u09c7\\u09b6\\u09a8 \\u09b0\\u09bf\\u09aa\\u09cb\\u09b0\\u09cd\\u099f\\u09bf\\u0982 \\u09b8\\u09b9 \\u09b8\\u09c0\\u09ae\\u09be\\u09b9\\u09c0\\u09a8 \\u0997\\u09c1\\u09a6\\u09be\\u09ae \\u09b8\\u09ae\\u09b0\\u09cd\\u09a5\\u09a8 \\u0995\\u09b0\\u09c7\\u0964\"},\"tr\":{\"question\":\"Birden fazla depo y\\u00f6netebilir miyim?\",\"answer\":\"Evet. T\\u00fcm \\u00fccretli planlar stok transferleri, ayarlamalar ve lokasyon bazl\\u0131 raporlama ile s\\u0131n\\u0131rs\\u0131z depo destekler.\"},\"de\":{\"question\":\"Kann ich mehrere Lager verwalten?\",\"answer\":\"Ja. Alle kostenpflichtigen Pl\\u00e4ne unterst\\u00fctzen unbegrenzte Lager mit Bestandstransfers, Anpassungen und standortbezogenen Berichten.\"},\"pt\":{\"question\":\"Posso gerenciar v\\u00e1rios armaz\\u00e9ns?\",\"answer\":\"Sim. Todos os planos pagos suportam armaz\\u00e9ns ilimitados com transfer\\u00eancias de estoque, ajustes e relat\\u00f3rios por localiza\\u00e7\\u00e3o.\"}}', 'Can I manage multiple warehouses?', 'Yes. All paid plans support unlimited warehouses with stock transfers, adjustments, and per-location reporting.', 2, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15'),
(3, '{\"fr\":{\"question\":\"Mes donn\\u00e9es sont-elles s\\u00e9curis\\u00e9es ?\",\"answer\":\"Absolument. Chaque espace de travail dispose de sa propre base de donn\\u00e9es isol\\u00e9e, de connexions chiffr\\u00e9es et de sauvegardes quotidiennes automatiques.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a\\u064a \\u0622\\u0645\\u0646\\u0629\\u061f\",\"answer\":\"\\u0628\\u0627\\u0644\\u062a\\u0623\\u0643\\u064a\\u062f. \\u0643\\u0644 \\u0645\\u0633\\u0627\\u062d\\u0629 \\u0639\\u0645\\u0644 \\u0644\\u062f\\u064a\\u0647\\u0627 \\u0642\\u0627\\u0639\\u062f\\u0629 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0645\\u0639\\u0632\\u0648\\u0644\\u0629 \\u062e\\u0627\\u0635\\u0629 \\u0628\\u0647\\u0627\\u060c \\u0648\\u0627\\u062a\\u0635\\u0627\\u0644\\u0627\\u062a \\u0645\\u0634\\u0641\\u0631\\u0629\\u060c \\u0648\\u0646\\u0633\\u062e \\u0627\\u062d\\u062a\\u064a\\u0627\\u0637\\u064a\\u0629 \\u064a\\u0648\\u0645\\u064a\\u0629 \\u062a\\u0644\\u0642\\u0627\\u0626\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfEst\\u00e1n seguros mis datos?\",\"answer\":\"Absolutamente. Cada espacio de trabajo tiene su propia base de datos aislada, conexiones cifradas y copias de seguridad diarias autom\\u00e1ticas.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0947\\u0930\\u093e \\u0921\\u0947\\u091f\\u093e \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0939\\u0948?\",\"answer\":\"\\u092c\\u093f\\u0932\\u094d\\u0915\\u0941\\u0932\\u0964 \\u0939\\u0930 \\u0915\\u093e\\u0930\\u094d\\u092f\\u0915\\u094d\\u0937\\u0947\\u0924\\u094d\\u0930 \\u0915\\u0940 \\u0905\\u092a\\u0928\\u0940 \\u0905\\u0932\\u0917 \\u0921\\u0947\\u091f\\u093e\\u092c\\u0947\\u0938, \\u090f\\u0928\\u094d\\u0915\\u094d\\u0930\\u093f\\u092a\\u094d\\u091f\\u0947\\u0921 \\u0915\\u0928\\u0947\\u0915\\u094d\\u0936\\u0928 \\u0914\\u0930 \\u0938\\u094d\\u0935\\u091a\\u093e\\u0932\\u093f\\u0924 \\u0926\\u0948\\u0928\\u093f\\u0915 \\u092c\\u0948\\u0915\\u0905\\u092a \\u0939\\u094b\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"},\"bn\":{\"question\":\"\\u0986\\u09ae\\u09be\\u09b0 \\u09a1\\u09c7\\u099f\\u09be \\u0995\\u09bf \\u09a8\\u09bf\\u09b0\\u09be\\u09aa\\u09a6?\",\"answer\":\"\\u0985\\u09ac\\u09b6\\u09cd\\u09af\\u0987\\u0964 \\u09aa\\u09cd\\u09b0\\u09a4\\u09bf\\u099f\\u09bf \\u0993\\u09af\\u09bc\\u09be\\u09b0\\u09cd\\u0995\\u09b8\\u09cd\\u09aa\\u09c7\\u09b8\\u09c7\\u09b0 \\u09a8\\u09bf\\u099c\\u09b8\\u09cd\\u09ac \\u09ac\\u09bf\\u099a\\u09cd\\u099b\\u09bf\\u09a8\\u09cd\\u09a8 \\u09a1\\u09c7\\u099f\\u09be\\u09ac\\u09c7\\u09b8, \\u098f\\u09a8\\u0995\\u09cd\\u09b0\\u09bf\\u09aa\\u09cd\\u099f\\u09c7\\u09a1 \\u0995\\u09be\\u09a8\\u09c7\\u0995\\u09b6\\u09a8 \\u098f\\u09ac\\u0982 \\u09b8\\u09cd\\u09ac\\u09af\\u09bc\\u0982\\u0995\\u09cd\\u09b0\\u09bf\\u09af\\u09bc \\u09a6\\u09c8\\u09a8\\u09bf\\u0995 \\u09ac\\u09cd\\u09af\\u09be\\u0995\\u0986\\u09aa \\u0986\\u099b\\u09c7\\u0964\"},\"tr\":{\"question\":\"Verilerim g\\u00fcvende mi?\",\"answer\":\"Kesinlikle. Her \\u00e7al\\u0131\\u015fma alan\\u0131n\\u0131n kendi izole veritaban\\u0131, \\u015fifreli ba\\u011flant\\u0131lar\\u0131 ve otomatik g\\u00fcnl\\u00fck yedeklemeleri vard\\u0131r.\"},\"de\":{\"question\":\"Sind meine Daten sicher?\",\"answer\":\"Absolut. Jeder Arbeitsbereich hat seine eigene isolierte Datenbank, verschl\\u00fcsselte Verbindungen und automatische t\\u00e4gliche Backups.\"},\"pt\":{\"question\":\"Meus dados est\\u00e3o seguros?\",\"answer\":\"Com certeza. Cada espa\\u00e7o de trabalho tem seu pr\\u00f3prio banco de dados isolado, conex\\u00f5es criptografadas e backups di\\u00e1rios autom\\u00e1ticos.\"}}', 'Is my data secure?', 'Absolutely. Each workspace has its own isolated database, encrypted connections, and automatic daily backups.', 3, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15'),
(4, '{\"fr\":{\"question\":\"Puis-je importer mes produits existants ?\",\"answer\":\"Oui. Vous pouvez importer en masse des produits, clients et fournisseurs via CSV. Nous offrons aussi la synchronisation WooCommerce pour les boutiques en ligne.\"},\"ar\":{\"question\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0633\\u062a\\u064a\\u0631\\u0627\\u062f \\u0645\\u0646\\u062a\\u062c\\u0627\\u062a\\u064a \\u0627\\u0644\\u062d\\u0627\\u0644\\u064a\\u0629\\u061f\",\"answer\":\"\\u0646\\u0639\\u0645. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0627\\u0633\\u062a\\u064a\\u0631\\u0627\\u062f \\u0627\\u0644\\u0645\\u0646\\u062a\\u062c\\u0627\\u062a \\u0648\\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0648\\u0627\\u0644\\u0645\\u0648\\u0631\\u062f\\u064a\\u0646 \\u0628\\u0634\\u0643\\u0644 \\u0645\\u062c\\u0645\\u0639 \\u0639\\u0628\\u0631 CSV. \\u0643\\u0645\\u0627 \\u0646\\u0648\\u0641\\u0631 \\u0645\\u0632\\u0627\\u0645\\u0646\\u0629 \\u0648\\u0648\\u0643\\u0648\\u0645\\u0631\\u0633 \\u0644\\u0644\\u0645\\u062a\\u0627\\u062c\\u0631 \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a\\u0629.\"},\"es\":{\"question\":\"\\u00bfPuedo importar mis productos existentes?\",\"answer\":\"S\\u00ed. Puedes importar productos, clientes y proveedores masivamente por CSV. Tambi\\u00e9n ofrecemos sincronizaci\\u00f3n con WooCommerce para tiendas en l\\u00ednea.\"},\"hi\":{\"question\":\"\\u0915\\u094d\\u092f\\u093e \\u092e\\u0948\\u0902 \\u0905\\u092a\\u0928\\u0947 \\u092e\\u094c\\u091c\\u0942\\u0926\\u093e \\u0909\\u0924\\u094d\\u092a\\u093e\\u0926 \\u0906\\u092f\\u093e\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0902?\",\"answer\":\"\\u0939\\u093e\\u0902\\u0964 \\u0906\\u092a CSV \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u0909\\u0924\\u094d\\u092a\\u093e\\u0926, \\u0917\\u094d\\u0930\\u093e\\u0939\\u0915 \\u0914\\u0930 \\u0906\\u092a\\u0942\\u0930\\u094d\\u0924\\u093f\\u0915\\u0930\\u094d\\u0924\\u093e \\u092c\\u0932\\u094d\\u0915-\\u0907\\u092e\\u094d\\u092a\\u094b\\u0930\\u094d\\u091f \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0939\\u092e \\u0911\\u0928\\u0932\\u093e\\u0907\\u0928 \\u0938\\u094d\\u091f\\u094b\\u0930 \\u0915\\u0947 \\u0932\\u093f\\u090f WooCommerce \\u0938\\u093f\\u0902\\u0915 \\u092d\\u0940 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\"},\"bn\":{\"question\":\"\\u0986\\u09ae\\u09bf \\u0995\\u09bf \\u0986\\u09ae\\u09be\\u09b0 \\u09ac\\u09bf\\u09a6\\u09cd\\u09af\\u09ae\\u09be\\u09a8 \\u09aa\\u09a3\\u09cd\\u09af \\u0986\\u09ae\\u09a6\\u09be\\u09a8\\u09bf \\u0995\\u09b0\\u09a4\\u09c7 \\u09aa\\u09be\\u09b0\\u09bf?\",\"answer\":\"\\u09b9\\u09cd\\u09af\\u09be\\u0981\\u0964 \\u0986\\u09aa\\u09a8\\u09bf CSV-\\u098f\\u09b0 \\u09ae\\u09be\\u09a7\\u09cd\\u09af\\u09ae\\u09c7 \\u09aa\\u09a3\\u09cd\\u09af, \\u0995\\u09cd\\u09b2\\u09be\\u09af\\u09bc\\u09c7\\u09a8\\u09cd\\u099f \\u098f\\u09ac\\u0982 \\u09b8\\u09b0\\u09ac\\u09b0\\u09be\\u09b9\\u0995\\u09be\\u09b0\\u09c0 \\u09ac\\u09be\\u09b2\\u09cd\\u0995-\\u0987\\u09ae\\u09aa\\u09cb\\u09b0\\u09cd\\u099f \\u0995\\u09b0\\u09a4\\u09c7 \\u09aa\\u09be\\u09b0\\u09c7\\u09a8\\u0964 \\u0986\\u09ae\\u09b0\\u09be \\u0985\\u09a8\\u09b2\\u09be\\u0987\\u09a8 \\u09b8\\u09cd\\u099f\\u09cb\\u09b0\\u09c7\\u09b0 \\u099c\\u09a8\\u09cd\\u09af WooCommerce \\u09b8\\u09bf\\u0999\\u09cd\\u0995\\u0993 \\u0985\\u09ab\\u09be\\u09b0 \\u0995\\u09b0\\u09bf\\u0964\"},\"tr\":{\"question\":\"Mevcut \\u00fcr\\u00fcnlerimi i\\u00e7e aktarabilir miyim?\",\"answer\":\"Evet. CSV ile \\u00fcr\\u00fcnleri, m\\u00fc\\u015fterileri ve tedarik\\u00e7ileri toplu olarak i\\u00e7e aktarabilirsiniz. \\u00c7evrimi\\u00e7i ma\\u011fazalar i\\u00e7in WooCommerce senkronizasyonu da sunuyoruz.\"},\"de\":{\"question\":\"Kann ich meine bestehenden Produkte importieren?\",\"answer\":\"Ja. Sie k\\u00f6nnen Produkte, Kunden und Lieferanten per CSV-Massenimport hochladen. Wir bieten auch WooCommerce-Synchronisation f\\u00fcr Online-Shops.\"},\"pt\":{\"question\":\"Posso importar meus produtos existentes?\",\"answer\":\"Sim. Voc\\u00ea pode importar produtos, clientes e fornecedores em massa via CSV. Tamb\\u00e9m oferecemos sincroniza\\u00e7\\u00e3o com WooCommerce para lojas online.\"}}', 'Can I import my existing products?', 'Yes. You can bulk-import products, clients, and suppliers via CSV. We also offer WooCommerce sync for online stores.', 4, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15'),
(5, '{\"fr\":{\"question\":\"Quels moyens de paiement acceptez-vous ?\",\"answer\":\"Nous acceptons toutes les cartes de cr\\u00e9dit principales via Stripe, ainsi que PayPal, Paystack et Flutterwave selon votre r\\u00e9gion.\"},\"ar\":{\"question\":\"\\u0645\\u0627 \\u0637\\u0631\\u0642 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0627\\u0644\\u0645\\u0642\\u0628\\u0648\\u0644\\u0629 \\u0644\\u062f\\u064a\\u0643\\u0645\\u061f\",\"answer\":\"\\u0646\\u0642\\u0628\\u0644 \\u062c\\u0645\\u064a\\u0639 \\u0628\\u0637\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u0627\\u0626\\u062a\\u0645\\u0627\\u0646 \\u0627\\u0644\\u0631\\u0626\\u064a\\u0633\\u064a\\u0629 \\u0639\\u0628\\u0631 Stripe\\u060c \\u0628\\u0627\\u0644\\u0625\\u0636\\u0627\\u0641\\u0629 \\u0625\\u0644\\u0649 PayPal \\u0648Paystack \\u0648Flutterwave \\u062d\\u0633\\u0628 \\u0645\\u0646\\u0637\\u0642\\u062a\\u0643.\"},\"es\":{\"question\":\"\\u00bfQu\\u00e9 m\\u00e9todos de pago aceptan?\",\"answer\":\"Aceptamos todas las tarjetas de cr\\u00e9dito principales a trav\\u00e9s de Stripe, as\\u00ed como PayPal, Paystack y Flutterwave seg\\u00fan tu regi\\u00f3n.\"},\"hi\":{\"question\":\"\\u0906\\u092a \\u0915\\u094c\\u0928 \\u0938\\u0947 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0924\\u0930\\u0940\\u0915\\u0947 \\u0938\\u094d\\u0935\\u0940\\u0915\\u093e\\u0930 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902?\",\"answer\":\"\\u0939\\u092e Stripe \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u0938\\u092d\\u0940 \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0915\\u094d\\u0930\\u0947\\u0921\\u093f\\u091f \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0938\\u094d\\u0935\\u0940\\u0915\\u093e\\u0930 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u0938\\u093e\\u0925 \\u0939\\u0940 \\u0906\\u092a\\u0915\\u0947 \\u0915\\u094d\\u0937\\u0947\\u0924\\u094d\\u0930 \\u0915\\u0947 \\u0905\\u0928\\u0941\\u0938\\u093e\\u0930 PayPal, Paystack \\u0914\\u0930 Flutterwave \\u092d\\u0940\\u0964\"},\"bn\":{\"question\":\"\\u0986\\u09aa\\u09a8\\u09be\\u09b0\\u09be \\u0995\\u09cb\\u09a8 \\u09aa\\u09c7\\u09ae\\u09c7\\u09a8\\u09cd\\u099f \\u09aa\\u09a6\\u09cd\\u09a7\\u09a4\\u09bf \\u0997\\u09cd\\u09b0\\u09b9\\u09a3 \\u0995\\u09b0\\u09c7\\u09a8?\",\"answer\":\"\\u0986\\u09ae\\u09b0\\u09be Stripe-\\u098f\\u09b0 \\u09ae\\u09be\\u09a7\\u09cd\\u09af\\u09ae\\u09c7 \\u09b8\\u09ae\\u09b8\\u09cd\\u09a4 \\u09aa\\u09cd\\u09b0\\u09a7\\u09be\\u09a8 \\u0995\\u09cd\\u09b0\\u09c7\\u09a1\\u09bf\\u099f \\u0995\\u09be\\u09b0\\u09cd\\u09a1 \\u0997\\u09cd\\u09b0\\u09b9\\u09a3 \\u0995\\u09b0\\u09bf, \\u09b8\\u09c7\\u0987\\u09b8\\u09be\\u09a5\\u09c7 \\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u0985\\u099e\\u09cd\\u099a\\u09b2 \\u0985\\u09a8\\u09c1\\u09af\\u09be\\u09af\\u09bc\\u09c0 PayPal, Paystack \\u098f\\u09ac\\u0982 Flutterwave\\u0964\"},\"tr\":{\"question\":\"Hangi \\u00f6deme y\\u00f6ntemlerini kabul ediyorsunuz?\",\"answer\":\"Stripe \\u00fczerinden t\\u00fcm b\\u00fcy\\u00fck kredi kartlar\\u0131n\\u0131, ayr\\u0131ca b\\u00f6lgenize g\\u00f6re PayPal, Paystack ve Flutterwave\'i kabul ediyoruz.\"},\"de\":{\"question\":\"Welche Zahlungsmethoden akzeptieren Sie?\",\"answer\":\"Wir akzeptieren alle g\\u00e4ngigen Kreditkarten \\u00fcber Stripe sowie PayPal, Paystack und Flutterwave je nach Region.\"},\"pt\":{\"question\":\"Quais m\\u00e9todos de pagamento voc\\u00eas aceitam?\",\"answer\":\"Aceitamos todos os principais cart\\u00f5es de cr\\u00e9dito via Stripe, al\\u00e9m de PayPal, Paystack e Flutterwave dependendo da sua regi\\u00e3o.\"}}', 'What payment methods do you accept?', 'We accept all major credit cards via Stripe, as well as PayPal, Paystack, and Flutterwave depending on your region.', 5, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15');

