INSERT INTO `landing_hero` (`id`, `translations`, `title`, `subtitle`, `description`, `primary_button_text`, `primary_button_url`, `secondary_button_text`, `secondary_button_url`, `hero_image`, `background_image`, `is_active`, `created_at`, `updated_at`) VALUES
(1, '{\"fr\":{\"title\":\"G\\u00e9rez votre inventaire plus intelligemment\",\"subtitle\":\"Plateforme de gestion de stock tout-en-un\",\"description\":\"Rationalisez vos op\\u00e9rations d\'entrep\\u00f4t, suivez les stocks en temps r\\u00e9el et d\\u00e9veloppez votre entreprise gr\\u00e2ce \\u00e0 un POS puissant, la facturation et la gestion multi-sites.\",\"primary_button_text\":\"Commencer gratuitement\",\"secondary_button_text\":\"En savoir plus\"},\"ar\":{\"title\":\"\\u0623\\u062f\\u0631 \\u0645\\u062e\\u0632\\u0648\\u0646\\u0643 \\u0628\\u0630\\u0643\\u0627\\u0621 \\u0623\\u0643\\u0628\\u0631\",\"subtitle\":\"\\u0645\\u0646\\u0635\\u0629 \\u0645\\u062a\\u0643\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u062e\\u0632\\u0648\\u0646\",\"description\":\"\\u0642\\u0645 \\u0628\\u062a\\u0628\\u0633\\u064a\\u0637 \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0627\\u0644\\u0645\\u0633\\u062a\\u0648\\u062f\\u0639\\u060c \\u0648\\u062a\\u062a\\u0628\\u0639 \\u0627\\u0644\\u0645\\u062e\\u0632\\u0648\\u0646 \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u0641\\u0639\\u0644\\u064a\\u060c \\u0648\\u0646\\u0645\\u0650\\u0651 \\u0623\\u0639\\u0645\\u0627\\u0644\\u0643 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0646\\u0642\\u0627\\u0637 \\u0628\\u064a\\u0639 \\u0642\\u0648\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0641\\u0648\\u062a\\u0631\\u0629 \\u0648\\u062f\\u0639\\u0645 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0642\\u0639 \\u0627\\u0644\\u0645\\u062a\\u0639\\u062f\\u062f\\u0629.\",\"primary_button_text\":\"\\u0627\\u0628\\u062f\\u0623 \\u0645\\u062c\\u0627\\u0646\\u064b\\u0627\",\"secondary_button_text\":\"\\u0627\\u0639\\u0631\\u0641 \\u0627\\u0644\\u0645\\u0632\\u064a\\u062f\"},\"es\":{\"title\":\"Gestiona tu inventario de forma m\\u00e1s inteligente\",\"subtitle\":\"Plataforma integral de gesti\\u00f3n de stock\",\"description\":\"Optimiza las operaciones de tu almac\\u00e9n, rastrea el stock en tiempo real y haz crecer tu negocio con un potente POS, facturaci\\u00f3n y soporte multi-ubicaci\\u00f3n.\",\"primary_button_text\":\"Comenzar gratis\",\"secondary_button_text\":\"M\\u00e1s informaci\\u00f3n\"},\"hi\":{\"title\":\"\\u0905\\u092a\\u0928\\u0940 \\u0907\\u0928\\u094d\\u0935\\u0947\\u0902\\u091f\\u094d\\u0930\\u0940 \\u0915\\u094b \\u0938\\u094d\\u092e\\u093e\\u0930\\u094d\\u091f \\u0924\\u0930\\u0940\\u0915\\u0947 \\u0938\\u0947 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902\",\"subtitle\":\"\\u0911\\u0932-\\u0907\\u0928-\\u0935\\u0928 \\u0938\\u094d\\u091f\\u0949\\u0915 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u0928 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e\",\"description\":\"\\u0905\\u092a\\u0928\\u0947 \\u0917\\u094b\\u0926\\u093e\\u092e \\u0938\\u0902\\u091a\\u093e\\u0932\\u0928 \\u0915\\u094b \\u0938\\u0941\\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902, \\u0930\\u0940\\u092f\\u0932 \\u091f\\u093e\\u0907\\u092e \\u092e\\u0947\\u0902 \\u0938\\u094d\\u091f\\u0949\\u0915 \\u091f\\u094d\\u0930\\u0948\\u0915 \\u0915\\u0930\\u0947\\u0902, \\u0914\\u0930 \\u0936\\u0915\\u094d\\u0924\\u093f\\u0936\\u093e\\u0932\\u0940 POS, \\u0907\\u0928\\u0935\\u0949\\u0907\\u0938\\u093f\\u0902\\u0917 \\u0914\\u0930 \\u092e\\u0932\\u094d\\u091f\\u0940-\\u0932\\u094b\\u0915\\u0947\\u0936\\u0928 \\u0938\\u092a\\u094b\\u0930\\u094d\\u091f \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0905\\u092a\\u0928\\u093e \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u092c\\u0922\\u093c\\u093e\\u090f\\u0902\\u0964\",\"primary_button_text\":\"\\u092e\\u0941\\u092b\\u094d\\u0924 \\u092e\\u0947\\u0902 \\u0936\\u0941\\u0930\\u0942 \\u0915\\u0930\\u0947\\u0902\",\"secondary_button_text\":\"\\u0914\\u0930 \\u091c\\u093e\\u0928\\u0947\\u0902\"},\"bn\":{\"title\":\"\\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u0987\\u09a8\\u09ad\\u09c7\\u09a8\\u09cd\\u099f\\u09b0\\u09bf \\u0986\\u09b0\\u0993 \\u09b8\\u09cd\\u09ae\\u09be\\u09b0\\u09cd\\u099f\\u09ad\\u09be\\u09ac\\u09c7 \\u09aa\\u09b0\\u09bf\\u099a\\u09be\\u09b2\\u09a8\\u09be \\u0995\\u09b0\\u09c1\\u09a8\",\"subtitle\":\"\\u0985\\u09b2-\\u0987\\u09a8-\\u0993\\u09af\\u09bc\\u09be\\u09a8 \\u09b8\\u09cd\\u099f\\u0995 \\u09ae\\u09cd\\u09af\\u09be\\u09a8\\u09c7\\u099c\\u09ae\\u09c7\\u09a8\\u09cd\\u099f \\u09aa\\u09cd\\u09b2\\u09cd\\u09af\\u09be\\u099f\\u09ab\\u09b0\\u09cd\\u09ae\",\"description\":\"\\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u0997\\u09c1\\u09a6\\u09be\\u09ae \\u09aa\\u09b0\\u09bf\\u099a\\u09be\\u09b2\\u09a8\\u09be \\u09b8\\u09b9\\u099c \\u0995\\u09b0\\u09c1\\u09a8, \\u09b0\\u09bf\\u09af\\u09bc\\u09c7\\u09b2 \\u099f\\u09be\\u0987\\u09ae\\u09c7 \\u09b8\\u09cd\\u099f\\u0995 \\u099f\\u09cd\\u09b0\\u09cd\\u09af\\u09be\\u0995 \\u0995\\u09b0\\u09c1\\u09a8 \\u098f\\u09ac\\u0982 \\u09b6\\u0995\\u09cd\\u09a4\\u09bf\\u09b6\\u09be\\u09b2\\u09c0 POS, \\u0987\\u09a8\\u09ad\\u09af\\u09bc\\u09c7\\u09b8\\u09bf\\u0982 \\u098f\\u09ac\\u0982 \\u09ae\\u09be\\u09b2\\u09cd\\u099f\\u09bf-\\u09b2\\u09cb\\u0995\\u09c7\\u09b6\\u09a8 \\u09b8\\u09be\\u09aa\\u09cb\\u09b0\\u09cd\\u099f \\u09a6\\u09bf\\u09af\\u09bc\\u09c7 \\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u09ac\\u09cd\\u09af\\u09ac\\u09b8\\u09be \\u09ac\\u09be\\u09a1\\u09bc\\u09be\\u09a8\\u0964\",\"primary_button_text\":\"\\u09ac\\u09bf\\u09a8\\u09be\\u09ae\\u09c2\\u09b2\\u09cd\\u09af\\u09c7 \\u09b6\\u09c1\\u09b0\\u09c1 \\u0995\\u09b0\\u09c1\\u09a8\",\"secondary_button_text\":\"\\u0986\\u09b0\\u0993 \\u099c\\u09be\\u09a8\\u09c1\\u09a8\"},\"tr\":{\"title\":\"Envanterinizi daha ak\\u0131ll\\u0131 y\\u00f6netin\",\"subtitle\":\"Hepsi bir arada stok y\\u00f6netim platformu\",\"description\":\"Depo operasyonlar\\u0131n\\u0131z\\u0131 kolayla\\u015ft\\u0131r\\u0131n, stoku ger\\u00e7ek zamanl\\u0131 takip edin ve g\\u00fc\\u00e7l\\u00fc POS, faturalama ve \\u00e7oklu lokasyon deste\\u011fiyle i\\u015finizi b\\u00fcy\\u00fct\\u00fcn.\",\"primary_button_text\":\"\\u00dccretsiz ba\\u015flay\\u0131n\",\"secondary_button_text\":\"Daha fazla bilgi\"},\"de\":{\"title\":\"Verwalten Sie Ihr Inventar intelligenter\",\"subtitle\":\"All-in-One Bestandsverwaltungsplattform\",\"description\":\"Optimieren Sie Ihre Lagerabl\\u00e4ufe, verfolgen Sie Best\\u00e4nde in Echtzeit und wachsen Sie mit leistungsstarkem POS, Rechnungsstellung und Multi-Standort-Unterst\\u00fctzung.\",\"primary_button_text\":\"Kostenlos starten\",\"secondary_button_text\":\"Mehr erfahren\"},\"pt\":{\"title\":\"Gerencie seu invent\\u00e1rio de forma mais inteligente\",\"subtitle\":\"Plataforma completa de gest\\u00e3o de estoque\",\"description\":\"Simplifique as opera\\u00e7\\u00f5es do seu armaz\\u00e9m, rastreie o estoque em tempo real e expanda seus neg\\u00f3cios com POS poderoso, faturamento e suporte multi-localiza\\u00e7\\u00e3o.\",\"primary_button_text\":\"Comece gratuitamente\",\"secondary_button_text\":\"Saiba mais\"}}', 'Manage Your Inventory Smarter', 'All-in-One Stock Management Platform', 'Streamline your warehouse operations, track stock in real time, and grow your business with powerful POS, invoicing, and multi-location support.', 'Start Free Trial', '/register', 'Learn More', '#features', NULL, NULL, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15');

