INSERT INTO `landing_how_it_works_steps` (`id`, `title`, `description`, `icon`, `icon_color`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Plan updates apply instantly', 'When new features or higher limits are added to your plan, you get immediate access. No need to re-subscribe or wait — changes are live in real time for all users on the plan.', 'bi bi-arrow-repeat', 'green', 1, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15'),
(2, 'Price changes are fair', 'If a plan price changes, your current billing period stays at the old rate. The new price only kicks in on your next renewal, so you are never charged more mid-cycle.', 'bi bi-credit-card', 'blue', 2, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15'),
(3, 'Plans cannot disappear on you', 'A plan with active subscribers can never be deleted. If a plan is retired, it is simply hidden from new signups — your access and features continue without interruption.', 'bi bi-shield-check', 'amber', 3, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15'),
(4, 'Your data is isolated & secure', 'Every workspace gets its own dedicated database. Your inventory, customers, and reports are completely separated from other businesses on the platform.', 'bi bi-database-lock', 'purple', 4, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15'),
(5, 'Try before you buy', 'Start with a free trial — full access to all features, no credit card required. When the trial ends, simply pick a plan to continue. Your data is preserved.', 'bi bi-clock-history', 'teal', 5, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15'),
(6, 'Upgrade or downgrade anytime', 'Switch plans whenever you need to. Upgrading gives you instant access to new features. Downgrading takes effect at the end of your current billing period.', 'bi bi-arrow-up-circle', 'red', 6, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15');

