INSERT INTO `landing_pricing` (`id`, `translations`, `section_title`, `section_subtitle`, `show_monthly_pricing`, `show_yearly_pricing`, `load_plans_from_database`, `is_active`, `created_at`, `updated_at`) VALUES
(1, '{\"fr\":{\"section_title\":\"Tarification simple et transparente\",\"section_subtitle\":\"Choisissez le plan adapt\\u00e9 \\u00e0 votre entreprise. Mettez \\u00e0 niveau ou r\\u00e9trogradez \\u00e0 tout moment.\"},\"ar\":{\"section_title\":\"\\u0623\\u0633\\u0639\\u0627\\u0631 \\u0628\\u0633\\u064a\\u0637\\u0629 \\u0648\\u0634\\u0641\\u0627\\u0641\\u0629\",\"section_subtitle\":\"\\u0627\\u062e\\u062a\\u0631 \\u0627\\u0644\\u062e\\u0637\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u0646\\u0627\\u0633\\u0628 \\u0639\\u0645\\u0644\\u0643. \\u0642\\u0645 \\u0628\\u0627\\u0644\\u062a\\u0631\\u0642\\u064a\\u0629 \\u0623\\u0648 \\u0627\\u0644\\u062a\\u062e\\u0641\\u064a\\u0636 \\u0641\\u064a \\u0623\\u064a \\u0648\\u0642\\u062a.\"},\"es\":{\"section_title\":\"Precios simples y transparentes\",\"section_subtitle\":\"Elige el plan que se adapte a tu negocio. Sube o baja de nivel en cualquier momento.\"},\"hi\":{\"section_title\":\"\\u0938\\u0930\\u0932, \\u092a\\u093e\\u0930\\u0926\\u0930\\u094d\\u0936\\u0940 \\u092e\\u0942\\u0932\\u094d\\u092f \\u0928\\u093f\\u0930\\u094d\\u0927\\u093e\\u0930\\u0923\",\"section_subtitle\":\"\\u0905\\u092a\\u0928\\u0947 \\u0935\\u094d\\u092f\\u0935\\u0938\\u093e\\u092f \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0909\\u092a\\u092f\\u0941\\u0915\\u094d\\u0924 \\u092a\\u094d\\u0932\\u093e\\u0928 \\u091a\\u0941\\u0928\\u0947\\u0902\\u0964 \\u0915\\u092d\\u0940 \\u092d\\u0940 \\u0905\\u092a\\u0917\\u094d\\u0930\\u0947\\u0921 \\u092f\\u093e \\u0921\\u093e\\u0909\\u0928\\u0917\\u094d\\u0930\\u0947\\u0921 \\u0915\\u0930\\u0947\\u0902\\u0964\"},\"bn\":{\"section_title\":\"\\u09b8\\u09b9\\u099c, \\u09b8\\u09cd\\u09ac\\u099a\\u09cd\\u099b \\u09ae\\u09c2\\u09b2\\u09cd\\u09af \\u09a8\\u09bf\\u09b0\\u09cd\\u09a7\\u09be\\u09b0\\u09a3\",\"section_subtitle\":\"\\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u09ac\\u09cd\\u09af\\u09ac\\u09b8\\u09be\\u09b0 \\u099c\\u09a8\\u09cd\\u09af \\u0989\\u09aa\\u09af\\u09c1\\u0995\\u09cd\\u09a4 \\u09aa\\u09cd\\u09b2\\u09cd\\u09af\\u09be\\u09a8 \\u09ac\\u09c7\\u099b\\u09c7 \\u09a8\\u09bf\\u09a8\\u0964 \\u09af\\u09c7\\u0995\\u09cb\\u09a8\\u09cb \\u09b8\\u09ae\\u09af\\u09bc \\u0986\\u09aa\\u0997\\u09cd\\u09b0\\u09c7\\u09a1 \\u09ac\\u09be \\u09a1\\u09be\\u0989\\u09a8\\u0997\\u09cd\\u09b0\\u09c7\\u09a1 \\u0995\\u09b0\\u09c1\\u09a8\\u0964\"},\"tr\":{\"section_title\":\"Basit, \\u015feffaf fiyatland\\u0131rma\",\"section_subtitle\":\"\\u0130\\u015fletmenize uygun plan\\u0131 se\\u00e7in. \\u0130stedi\\u011finiz zaman y\\u00fckseltin veya d\\u00fc\\u015f\\u00fcr\\u00fcn.\"},\"de\":{\"section_title\":\"Einfache, transparente Preisgestaltung\",\"section_subtitle\":\"W\\u00e4hlen Sie den Plan, der zu Ihrem Unternehmen passt. Jederzeit upgraden oder downgraden.\"},\"pt\":{\"section_title\":\"Pre\\u00e7os simples e transparentes\",\"section_subtitle\":\"Escolha o plano que se adapta ao seu neg\\u00f3cio. Fa\\u00e7a upgrade ou downgrade a qualquer momento.\"}}', 'Simple, Transparent Pricing', 'Choose the plan that fits your business. Upgrade or downgrade anytime.', 1, 1, 1, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15');

