INSERT INTO `landing_privacy_policy` (`id`, `translations`, `introduction`, `data_collection`, `data_usage`, `cookies_usage`, `third_party`, `data_protection`, `user_rights`, `contact_info`, `last_updated`, `is_active`, `created_at`, `updated_at`) VALUES
(1, '{\"fr\":{\"introduction\":\"Nous nous engageons \\u00e0 prot\\u00e9ger votre vie priv\\u00e9e. Cette politique de confidentialit\\u00e9 explique comment nous collectons, utilisons, divulguons et prot\\u00e9geons vos informations lorsque vous utilisez notre plateforme.\",\"data_collection\":\"Nous collectons les informations que vous fournissez directement, telles que votre nom, adresse e-mail, nom de l\'entreprise et d\\u00e9tails de paiement lors de votre inscription ou abonnement. Nous collectons \\u00e9galement automatiquement des donn\\u00e9es d\'utilisation, des informations sur l\'appareil et des cookies.\",\"data_usage\":\"Nous utilisons les informations collect\\u00e9es pour fournir et maintenir nos services, traiter les transactions, envoyer des notifications importantes, am\\u00e9liorer notre plateforme et respecter nos obligations l\\u00e9gales.\",\"cookies_usage\":\"Nous utilisons des cookies et des technologies de suivi similaires pour am\\u00e9liorer votre exp\\u00e9rience de navigation, analyser le trafic du site et personnaliser le contenu. Vous pouvez contr\\u00f4ler les pr\\u00e9f\\u00e9rences de cookies via les param\\u00e8tres de votre navigateur ou notre outil de consentement.\",\"third_party\":\"Nous pouvons partager vos donn\\u00e9es avec des prestataires de services tiers de confiance qui nous aident \\u00e0 exploiter notre plateforme, traiter les paiements et analyser l\'utilisation. Ces prestataires sont contractuellement tenus de prot\\u00e9ger vos donn\\u00e9es.\",\"data_protection\":\"Nous mettons en \\u0153uvre des mesures de s\\u00e9curit\\u00e9 conformes aux normes de l\'industrie, notamment le chiffrement, des serveurs s\\u00e9curis\\u00e9s et des contr\\u00f4les d\'acc\\u00e8s pour prot\\u00e9ger vos donn\\u00e9es personnelles. Chaque espace de travail dispose de sa propre base de donn\\u00e9es isol\\u00e9e pour une s\\u00e9paration maximale des donn\\u00e9es.\",\"user_rights\":\"Vous avez le droit d\'acc\\u00e9der, de corriger ou de supprimer vos donn\\u00e9es personnelles. Vous pouvez \\u00e9galement vous opposer au traitement, demander la portabilit\\u00e9 des donn\\u00e9es ou retirer votre consentement \\u00e0 tout moment en nous contactant.\",\"contact_info\":\"Si vous avez des questions concernant cette politique de confidentialit\\u00e9, veuillez nous contacter \\u00e0 :\"},\"ar\":{\"introduction\":\"\\u0646\\u062d\\u0646 \\u0645\\u0644\\u062a\\u0632\\u0645\\u0648\\u0646 \\u0628\\u062d\\u0645\\u0627\\u064a\\u0629 \\u062e\\u0635\\u0648\\u0635\\u064a\\u062a\\u0643. \\u062a\\u0648\\u0636\\u062d \\u0633\\u064a\\u0627\\u0633\\u0629 \\u0627\\u0644\\u062e\\u0635\\u0648\\u0635\\u064a\\u0629 \\u0647\\u0630\\u0647 \\u0643\\u064a\\u0641\\u064a\\u0629 \\u062c\\u0645\\u0639 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a\\u0643 \\u0648\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645\\u0647\\u0627 \\u0648\\u0627\\u0644\\u0625\\u0641\\u0635\\u0627\\u062d \\u0639\\u0646\\u0647\\u0627 \\u0648\\u062d\\u0645\\u0627\\u064a\\u062a\\u0647\\u0627 \\u0639\\u0646\\u062f \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0645\\u0646\\u0635\\u062a\\u0646\\u0627.\",\"data_collection\":\"\\u0646\\u062c\\u0645\\u0639 \\u0627\\u0644\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u062a\\u0642\\u062f\\u0645\\u0647\\u0627 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629\\u060c \\u0645\\u062b\\u0644 \\u0627\\u0633\\u0645\\u0643 \\u0648\\u0639\\u0646\\u0648\\u0627\\u0646 \\u0628\\u0631\\u064a\\u062f\\u0643 \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a \\u0648\\u0627\\u0633\\u0645 \\u0627\\u0644\\u0634\\u0631\\u0643\\u0629 \\u0648\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u062f\\u0641\\u0639 \\u0639\\u0646\\u062f \\u0627\\u0644\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0623\\u0648 \\u0627\\u0644\\u0627\\u0634\\u062a\\u0631\\u0627\\u0643. \\u0643\\u0645\\u0627 \\u0646\\u062c\\u0645\\u0639 \\u062a\\u0644\\u0642\\u0627\\u0626\\u064a\\u064b\\u0627 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0627\\u0644\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0648\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0648\\u0645\\u0644\\u0641\\u0627\\u062a \\u062a\\u0639\\u0631\\u064a\\u0641 \\u0627\\u0644\\u0627\\u0631\\u062a\\u0628\\u0627\\u0637.\",\"data_usage\":\"\\u0646\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0627\\u0644\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u0646\\u062c\\u0645\\u0639\\u0647\\u0627 \\u0644\\u062a\\u0642\\u062f\\u064a\\u0645 \\u062e\\u062f\\u0645\\u0627\\u062a\\u0646\\u0627 \\u0648\\u0635\\u064a\\u0627\\u0646\\u062a\\u0647\\u0627\\u060c \\u0648\\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u060c \\u0648\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0625\\u0634\\u0639\\u0627\\u0631\\u0627\\u062a \\u0645\\u0647\\u0645\\u0629\\u060c \\u0648\\u062a\\u062d\\u0633\\u064a\\u0646 \\u0645\\u0646\\u0635\\u062a\\u0646\\u0627\\u060c \\u0648\\u0627\\u0644\\u0627\\u0645\\u062a\\u062b\\u0627\\u0644 \\u0644\\u0644\\u0627\\u0644\\u062a\\u0632\\u0627\\u0645\\u0627\\u062a \\u0627\\u0644\\u0642\\u0627\\u0646\\u0648\\u0646\\u064a\\u0629.\",\"cookies_usage\":\"\\u0646\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0645\\u0644\\u0641\\u0627\\u062a \\u062a\\u0639\\u0631\\u064a\\u0641 \\u0627\\u0644\\u0627\\u0631\\u062a\\u0628\\u0627\\u0637 \\u0648\\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0627\\u0644\\u062a\\u062a\\u0628\\u0639 \\u0627\\u0644\\u0645\\u0645\\u0627\\u062b\\u0644\\u0629 \\u0644\\u062a\\u062d\\u0633\\u064a\\u0646 \\u062a\\u062c\\u0631\\u0628\\u0629 \\u0627\\u0644\\u062a\\u0635\\u0641\\u062d\\u060c \\u0648\\u062a\\u062d\\u0644\\u064a\\u0644 \\u062d\\u0631\\u0643\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0648\\u0642\\u0639\\u060c \\u0648\\u062a\\u062e\\u0635\\u064a\\u0635 \\u0627\\u0644\\u0645\\u062d\\u062a\\u0648\\u0649. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0627\\u0644\\u062a\\u062d\\u0643\\u0645 \\u0641\\u064a \\u062a\\u0641\\u0636\\u064a\\u0644\\u0627\\u062a \\u0645\\u0644\\u0641\\u0627\\u062a \\u062a\\u0639\\u0631\\u064a\\u0641 \\u0627\\u0644\\u0627\\u0631\\u062a\\u0628\\u0627\\u0637 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u0645\\u062a\\u0635\\u0641\\u062d \\u0623\\u0648 \\u0623\\u062f\\u0627\\u0629 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0641\\u0642\\u0629 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0646\\u0627.\",\"third_party\":\"\\u0642\\u062f \\u0646\\u0634\\u0627\\u0631\\u0643 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a\\u0643 \\u0645\\u0639 \\u0645\\u0632\\u0648\\u062f\\u064a \\u062e\\u062f\\u0645\\u0627\\u062a \\u0637\\u0631\\u0641 \\u062b\\u0627\\u0644\\u062b \\u0645\\u0648\\u062b\\u0648\\u0642\\u064a\\u0646 \\u064a\\u0633\\u0627\\u0639\\u062f\\u0648\\u0646\\u0646\\u0627 \\u0641\\u064a \\u062a\\u0634\\u063a\\u064a\\u0644 \\u0645\\u0646\\u0635\\u062a\\u0646\\u0627 \\u0648\\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0627\\u0644\\u0645\\u062f\\u0641\\u0648\\u0639\\u0627\\u062a \\u0648\\u062a\\u062d\\u0644\\u064a\\u0644 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645. \\u0647\\u0624\\u0644\\u0627\\u0621 \\u0627\\u0644\\u0645\\u0632\\u0648\\u062f\\u0648\\u0646 \\u0645\\u0644\\u0632\\u0645\\u0648\\u0646 \\u062a\\u0639\\u0627\\u0642\\u062f\\u064a\\u064b\\u0627 \\u0628\\u062d\\u0645\\u0627\\u064a\\u0629 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a\\u0643.\",\"data_protection\":\"\\u0646\\u0637\\u0628\\u0642 \\u0625\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u0623\\u0645\\u0627\\u0646 \\u0645\\u062a\\u0648\\u0627\\u0641\\u0642\\u0629 \\u0645\\u0639 \\u0645\\u0639\\u0627\\u064a\\u064a\\u0631 \\u0627\\u0644\\u0635\\u0646\\u0627\\u0639\\u0629 \\u0628\\u0645\\u0627 \\u0641\\u064a \\u0630\\u0644\\u0643 \\u0627\\u0644\\u062a\\u0634\\u0641\\u064a\\u0631 \\u0648\\u0627\\u0644\\u062e\\u0648\\u0627\\u062f\\u0645 \\u0627\\u0644\\u0622\\u0645\\u0646\\u0629 \\u0648\\u0636\\u0648\\u0627\\u0628\\u0637 \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0644\\u062d\\u0645\\u0627\\u064a\\u0629 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a\\u0643 \\u0627\\u0644\\u0634\\u062e\\u0635\\u064a\\u0629. \\u064a\\u062d\\u062a\\u0648\\u064a \\u0643\\u0644 \\u0645\\u0633\\u0627\\u062d\\u0629 \\u0639\\u0645\\u0644 \\u0639\\u0644\\u0649 \\u0642\\u0627\\u0639\\u062f\\u0629 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0645\\u0639\\u0632\\u0648\\u0644\\u0629 \\u062e\\u0627\\u0635\\u0629 \\u0628\\u0647\\u0627 \\u0644\\u062a\\u062d\\u0642\\u064a\\u0642 \\u0623\\u0642\\u0635\\u0649 \\u0641\\u0635\\u0644 \\u0644\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a.\",\"user_rights\":\"\\u0644\\u062f\\u064a\\u0643 \\u0627\\u0644\\u062d\\u0642 \\u0641\\u064a \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a\\u0643 \\u0627\\u0644\\u0634\\u062e\\u0635\\u064a\\u0629 \\u0623\\u0648 \\u062a\\u0635\\u062d\\u064a\\u062d\\u0647\\u0627 \\u0623\\u0648 \\u062d\\u0630\\u0641\\u0647\\u0627. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0623\\u064a\\u0636\\u064b\\u0627 \\u0627\\u0644\\u0627\\u0639\\u062a\\u0631\\u0627\\u0636 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0623\\u0648 \\u0637\\u0644\\u0628 \\u0646\\u0642\\u0644 \\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0623\\u0648 \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0641\\u0642\\u0629 \\u0641\\u064a \\u0623\\u064a \\u0648\\u0642\\u062a \\u0639\\u0646 \\u0637\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0627\\u062a\\u0635\\u0627\\u0644 \\u0628\\u0646\\u0627.\",\"contact_info\":\"\\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646\\u062a \\u0644\\u062f\\u064a\\u0643 \\u0623\\u064a \\u0623\\u0633\\u0626\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0633\\u064a\\u0627\\u0633\\u0629 \\u0627\\u0644\\u062e\\u0635\\u0648\\u0635\\u064a\\u0629 \\u0647\\u0630\\u0647\\u060c \\u064a\\u0631\\u062c\\u0649 \\u0627\\u0644\\u0627\\u062a\\u0635\\u0627\\u0644 \\u0628\\u0646\\u0627 \\u0639\\u0644\\u0649:\"},\"es\":{\"introduction\":\"Nos comprometemos a proteger su privacidad. Esta Pol\\u00edtica de Privacidad explica c\\u00f3mo recopilamos, usamos, divulgamos y protegemos su informaci\\u00f3n cuando utiliza nuestra plataforma.\",\"data_collection\":\"Recopilamos la informaci\\u00f3n que proporciona directamente, como su nombre, direcci\\u00f3n de correo electr\\u00f3nico, nombre de la empresa y detalles de pago al registrarse o suscribirse. Tambi\\u00e9n recopilamos autom\\u00e1ticamente datos de uso, informaci\\u00f3n del dispositivo y cookies.\",\"data_usage\":\"Utilizamos la informaci\\u00f3n recopilada para proporcionar y mantener nuestros servicios, procesar transacciones, enviar notificaciones importantes, mejorar nuestra plataforma y cumplir con obligaciones legales.\",\"cookies_usage\":\"Utilizamos cookies y tecnolog\\u00edas de seguimiento similares para mejorar su experiencia de navegaci\\u00f3n, analizar el tr\\u00e1fico del sitio y personalizar el contenido. Puede controlar las preferencias de cookies a trav\\u00e9s de la configuraci\\u00f3n de su navegador o nuestra herramienta de consentimiento.\",\"third_party\":\"Podemos compartir sus datos con proveedores de servicios de terceros de confianza que nos ayudan a operar nuestra plataforma, procesar pagos y analizar el uso. Estos proveedores est\\u00e1n obligados contractualmente a proteger sus datos.\",\"data_protection\":\"Implementamos medidas de seguridad est\\u00e1ndar de la industria, incluyendo cifrado, servidores seguros y controles de acceso para proteger sus datos personales. Cada espacio de trabajo tiene su propia base de datos aislada para m\\u00e1xima separaci\\u00f3n de datos.\",\"user_rights\":\"Tiene derecho a acceder, corregir o eliminar sus datos personales. Tambi\\u00e9n puede oponerse al procesamiento, solicitar la portabilidad de datos o retirar su consentimiento en cualquier momento contact\\u00e1ndonos.\",\"contact_info\":\"Si tiene alguna pregunta sobre esta Pol\\u00edtica de Privacidad, cont\\u00e1ctenos en:\"},\"hi\":{\"introduction\":\"\\u0939\\u092e \\u0906\\u092a\\u0915\\u0940 \\u0917\\u094b\\u092a\\u0928\\u0940\\u092f\\u0924\\u093e \\u0915\\u0940 \\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092a\\u094d\\u0930\\u0924\\u093f\\u092c\\u0926\\u094d\\u0927 \\u0939\\u0948\\u0902\\u0964 \\u092f\\u0939 \\u0917\\u094b\\u092a\\u0928\\u0940\\u092f\\u0924\\u093e \\u0928\\u0940\\u0924\\u093f \\u092c\\u0924\\u093e\\u0924\\u0940 \\u0939\\u0948 \\u0915\\u093f \\u091c\\u092c \\u0906\\u092a \\u0939\\u092e\\u093e\\u0930\\u0947 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902 \\u0924\\u094b \\u0939\\u092e \\u0906\\u092a\\u0915\\u0940 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0915\\u0948\\u0938\\u0947 \\u090f\\u0915\\u0924\\u094d\\u0930, \\u0909\\u092a\\u092f\\u094b\\u0917, \\u092a\\u094d\\u0930\\u0915\\u091f \\u0914\\u0930 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\",\"data_collection\":\"\\u0939\\u092e \\u0935\\u0939 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u090f\\u0915\\u0924\\u094d\\u0930 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902 \\u091c\\u094b \\u0906\\u092a \\u0938\\u0940\\u0927\\u0947 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902, \\u091c\\u0948\\u0938\\u0947 \\u0906\\u092a\\u0915\\u093e \\u0928\\u093e\\u092e, \\u0908\\u092e\\u0947\\u0932 \\u092a\\u0924\\u093e, \\u0915\\u0902\\u092a\\u0928\\u0940 \\u0915\\u093e \\u0928\\u093e\\u092e \\u0914\\u0930 \\u092a\\u0902\\u091c\\u0940\\u0915\\u0930\\u0923 \\u092f\\u093e \\u0938\\u0926\\u0938\\u094d\\u092f\\u0924\\u093e \\u0915\\u0947 \\u0938\\u092e\\u092f \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0935\\u093f\\u0935\\u0930\\u0923\\u0964 \\u0939\\u092e \\u0938\\u094d\\u0935\\u091a\\u093e\\u0932\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0921\\u0947\\u091f\\u093e, \\u0921\\u093f\\u0935\\u093e\\u0907\\u0938 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0914\\u0930 \\u0915\\u0941\\u0915\\u0940\\u091c\\u093c \\u092d\\u0940 \\u090f\\u0915\\u0924\\u094d\\u0930 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\",\"data_usage\":\"\\u0939\\u092e \\u090f\\u0915\\u0924\\u094d\\u0930\\u093f\\u0924 \\u091c\\u093e\\u0928\\u0915\\u093e\\u0930\\u0940 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0905\\u092a\\u0928\\u0940 \\u0938\\u0947\\u0935\\u093e\\u090f\\u0901 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u0914\\u0930 \\u092c\\u0928\\u093e\\u090f \\u0930\\u0916\\u0928\\u0947, \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928 \\u0938\\u0902\\u0938\\u093e\\u0927\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947, \\u092e\\u0939\\u0924\\u094d\\u0935\\u092a\\u0942\\u0930\\u094d\\u0923 \\u0938\\u0942\\u091a\\u0928\\u093e\\u090f\\u0901 \\u092d\\u0947\\u091c\\u0928\\u0947, \\u0905\\u092a\\u0928\\u0947 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u0915\\u094b \\u092c\\u0947\\u0939\\u0924\\u0930 \\u092c\\u0928\\u093e\\u0928\\u0947 \\u0914\\u0930 \\u0915\\u093e\\u0928\\u0942\\u0928\\u0940 \\u0926\\u093e\\u092f\\u093f\\u0924\\u094d\\u0935\\u094b\\u0902 \\u0915\\u093e \\u092a\\u093e\\u0932\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\",\"cookies_usage\":\"\\u0939\\u092e \\u0906\\u092a\\u0915\\u0947 \\u092c\\u094d\\u0930\\u093e\\u0909\\u091c\\u093c\\u093f\\u0902\\u0917 \\u0905\\u0928\\u0941\\u092d\\u0935 \\u0915\\u094b \\u092c\\u0947\\u0939\\u0924\\u0930 \\u092c\\u0928\\u093e\\u0928\\u0947, \\u0938\\u093e\\u0907\\u091f \\u091f\\u094d\\u0930\\u0948\\u092b\\u093c\\u093f\\u0915 \\u0915\\u093e \\u0935\\u093f\\u0936\\u094d\\u0932\\u0947\\u0937\\u0923 \\u0915\\u0930\\u0928\\u0947 \\u0914\\u0930 \\u0938\\u093e\\u092e\\u0917\\u094d\\u0930\\u0940 \\u0915\\u094b \\u0935\\u0948\\u092f\\u0915\\u094d\\u0924\\u093f\\u0915\\u0943\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0915\\u0941\\u0915\\u0940\\u091c\\u093c \\u0914\\u0930 \\u0938\\u092e\\u093e\\u0928 \\u091f\\u094d\\u0930\\u0948\\u0915\\u093f\\u0902\\u0917 \\u0924\\u0915\\u0928\\u0940\\u0915\\u094b\\u0902 \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u0906\\u092a \\u0905\\u092a\\u0928\\u0940 \\u092c\\u094d\\u0930\\u093e\\u0909\\u091c\\u093c\\u0930 \\u0938\\u0947\\u091f\\u093f\\u0902\\u0917\\u094d\\u0938 \\u092f\\u093e \\u0939\\u092e\\u093e\\u0930\\u0947 \\u0915\\u0941\\u0915\\u0940 \\u0938\\u0939\\u092e\\u0924\\u093f \\u091f\\u0942\\u0932 \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u0915\\u0941\\u0915\\u0940 \\u092a\\u094d\\u0930\\u093e\\u0925\\u092e\\u093f\\u0915\\u0924\\u093e\\u0913\\u0902 \\u0915\\u094b \\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u093f\\u0924 \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964\",\"third_party\":\"\\u0939\\u092e \\u0906\\u092a\\u0915\\u0947 \\u0921\\u0947\\u091f\\u093e \\u0915\\u094b \\u0935\\u093f\\u0936\\u094d\\u0935\\u0938\\u0928\\u0940\\u092f \\u0924\\u0943\\u0924\\u0940\\u092f-\\u092a\\u0915\\u094d\\u0937 \\u0938\\u0947\\u0935\\u093e \\u092a\\u094d\\u0930\\u0926\\u093e\\u0924\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0938\\u093e\\u091d\\u093e \\u0915\\u0930 \\u0938\\u0915\\u0924\\u0947 \\u0939\\u0948\\u0902 \\u091c\\u094b \\u0939\\u092e\\u093e\\u0930\\u0947 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u0915\\u094b \\u0938\\u0902\\u091a\\u093e\\u0932\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947, \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0938\\u0902\\u0938\\u093e\\u0927\\u093f\\u0924 \\u0915\\u0930\\u0928\\u0947 \\u0914\\u0930 \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u093e \\u0935\\u093f\\u0936\\u094d\\u0932\\u0947\\u0937\\u0923 \\u0915\\u0930\\u0928\\u0947 \\u092e\\u0947\\u0902 \\u0939\\u092e\\u093e\\u0930\\u0940 \\u0938\\u0939\\u093e\\u092f\\u0924\\u093e \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u092f\\u0947 \\u092a\\u094d\\u0930\\u0926\\u093e\\u0924\\u093e \\u0906\\u092a\\u0915\\u0947 \\u0921\\u0947\\u091f\\u093e \\u0915\\u0940 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u0928\\u0941\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0930\\u0942\\u092a \\u0938\\u0947 \\u092c\\u093e\\u0927\\u094d\\u092f \\u0939\\u0948\\u0902\\u0964\",\"data_protection\":\"\\u0939\\u092e \\u0906\\u092a\\u0915\\u0947 \\u0935\\u094d\\u092f\\u0915\\u094d\\u0924\\u093f\\u0917\\u0924 \\u0921\\u0947\\u091f\\u093e \\u0915\\u0940 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0915\\u0947 \\u0932\\u093f\\u090f \\u090f\\u0928\\u094d\\u0915\\u094d\\u0930\\u093f\\u092a\\u094d\\u0936\\u0928, \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0938\\u0930\\u094d\\u0935\\u0930 \\u0914\\u0930 \\u090f\\u0915\\u094d\\u0938\\u0947\\u0938 \\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u0923 \\u0938\\u0939\\u093f\\u0924 \\u0909\\u0926\\u094d\\u092f\\u094b\\u0917-\\u092e\\u093e\\u0928\\u0915 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e \\u0909\\u092a\\u093e\\u092f \\u0932\\u093e\\u0917\\u0942 \\u0915\\u0930\\u0924\\u0947 \\u0939\\u0948\\u0902\\u0964 \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u091f\\u0947\\u0928\\u0947\\u0902\\u091f \\u0915\\u093e\\u0930\\u094d\\u092f\\u0915\\u094d\\u0937\\u0947\\u0924\\u094d\\u0930 \\u092e\\u0947\\u0902 \\u0905\\u0927\\u093f\\u0915\\u0924\\u092e \\u0921\\u0947\\u091f\\u093e \\u092a\\u0943\\u0925\\u0915\\u094d\\u0915\\u0930\\u0923 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0905\\u092a\\u0928\\u093e \\u0938\\u094d\\u