INSERT INTO `landing_seo` (`id`, `translations`, `meta_title`, `meta_description`, `meta_keywords`, `og_image`, `favicon`, `created_at`, `updated_at`) VALUES
(1, '{\"fr\":{\"meta_title\":\"Quantro \\u2014 Plateforme de gestion d\'inventaire et de stock\",\"meta_description\":\"G\\u00e9rez l\'inventaire, les entrep\\u00f4ts, le POS, les achats et les ventes depuis une seule plateforme puissante. Commencez votre essai gratuit aujourd\'hui.\",\"meta_keywords\":\"gestion d\'inventaire, gestion de stock, POS, entrep\\u00f4t, multi-sites, SaaS\"},\"ar\":{\"meta_title\":\"Quantro \\u2014 \\u0645\\u0646\\u0635\\u0629 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u062e\\u0632\\u0648\\u0646 \\u0648\\u0627\\u0644\\u0645\\u0633\\u062a\\u0648\\u062f\\u0639\\u0627\\u062a\",\"meta_description\":\"\\u0623\\u062f\\u0631 \\u0627\\u0644\\u0645\\u062e\\u0632\\u0648\\u0646 \\u0648\\u0627\\u0644\\u0645\\u0633\\u062a\\u0648\\u062f\\u0639\\u0627\\u062a \\u0648\\u0646\\u0642\\u0627\\u0637 \\u0627\\u0644\\u0628\\u064a\\u0639 \\u0648\\u0627\\u0644\\u0645\\u0634\\u062a\\u0631\\u064a\\u0627\\u062a \\u0648\\u0627\\u0644\\u0645\\u0628\\u064a\\u0639\\u0627\\u062a \\u0645\\u0646 \\u0645\\u0646\\u0635\\u0629 \\u0648\\u0627\\u062d\\u062f\\u0629 \\u0642\\u0648\\u064a\\u0629. \\u0627\\u0628\\u062f\\u0623 \\u062a\\u062c\\u0631\\u0628\\u062a\\u0643 \\u0627\\u0644\\u0645\\u062c\\u0627\\u0646\\u064a\\u0629 \\u0627\\u0644\\u064a\\u0648\\u0645.\",\"meta_keywords\":\"\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u062e\\u0632\\u0648\\u0646, \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0648\\u062f\\u0639\\u0627\\u062a, \\u0646\\u0642\\u0627\\u0637 \\u0627\\u0644\\u0628\\u064a\\u0639, \\u0645\\u0633\\u062a\\u0648\\u062f\\u0639, \\u0645\\u062a\\u0639\\u062f\\u062f \\u0627\\u0644\\u0645\\u0648\\u0627\\u0642\\u0639, SaaS\"},\"es\":{\"meta_title\":\"Quantro \\u2014 Plataforma de gesti\\u00f3n de inventario y stock\",\"meta_description\":\"Gestiona inventario, almacenes, POS, compras y ventas desde una sola plataforma potente. Comienza tu prueba gratuita hoy.\",\"meta_keywords\":\"gesti\\u00f3n de inventario, gesti\\u00f3n de stock, POS, almac\\u00e9n, multi-ubicaci\\u00f3n, SaaS\"},\"hi\":{\"meta_title\":\"Quantro \\u2014 \\u0907\\u0928\\u094d\\u0935\\u0947\\u0902\\u091f\\u094d\\u0930\\u0940 \\u0914\\u0930 \\u0938\\u094d\\u091f\\u0949\\u0915 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u0928 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e\",\"meta_description\":\"\\u090f\\u0915 \\u0936\\u0915\\u094d\\u0924\\u093f\\u0936\\u093e\\u0932\\u0940 \\u092a\\u094d\\u0932\\u0947\\u091f\\u092b\\u093c\\u0949\\u0930\\u094d\\u092e \\u0938\\u0947 \\u0907\\u0928\\u094d\\u0935\\u0947\\u0902\\u091f\\u094d\\u0930\\u0940, \\u0917\\u094b\\u0926\\u093e\\u092e, POS, \\u0916\\u0930\\u0940\\u0926 \\u0914\\u0930 \\u092c\\u093f\\u0915\\u094d\\u0930\\u0940 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u093f\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0964 \\u0906\\u091c \\u0939\\u0940 \\u0905\\u092a\\u0928\\u093e \\u092e\\u0941\\u092b\\u094d\\u0924 \\u092a\\u0930\\u0940\\u0915\\u094d\\u0937\\u0923 \\u0936\\u0941\\u0930\\u0942 \\u0915\\u0930\\u0947\\u0902\\u0964\",\"meta_keywords\":\"\\u0907\\u0928\\u094d\\u0935\\u0947\\u0902\\u091f\\u094d\\u0930\\u0940 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u0928, \\u0938\\u094d\\u091f\\u0949\\u0915 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u0928, POS, \\u0917\\u094b\\u0926\\u093e\\u092e, \\u092e\\u0932\\u094d\\u091f\\u0940-\\u0932\\u094b\\u0915\\u0947\\u0936\\u0928, SaaS\"},\"bn\":{\"meta_title\":\"Quantro \\u2014 \\u0987\\u09a8\\u09ad\\u09c7\\u09a8\\u09cd\\u099f\\u09b0\\u09bf \\u0993 \\u09b8\\u09cd\\u099f\\u0995 \\u09ae\\u09cd\\u09af\\u09be\\u09a8\\u09c7\\u099c\\u09ae\\u09c7\\u09a8\\u09cd\\u099f \\u09aa\\u09cd\\u09b2\\u09cd\\u09af\\u09be\\u099f\\u09ab\\u09b0\\u09cd\\u09ae\",\"meta_description\":\"\\u098f\\u0995\\u099f\\u09bf \\u09b6\\u0995\\u09cd\\u09a4\\u09bf\\u09b6\\u09be\\u09b2\\u09c0 \\u09aa\\u09cd\\u09b2\\u09cd\\u09af\\u09be\\u099f\\u09ab\\u09b0\\u09cd\\u09ae \\u09a5\\u09c7\\u0995\\u09c7 \\u0987\\u09a8\\u09ad\\u09c7\\u09a8\\u09cd\\u099f\\u09b0\\u09bf, \\u0997\\u09c1\\u09a6\\u09be\\u09ae, POS, \\u0995\\u09cd\\u09b0\\u09af\\u09bc \\u098f\\u09ac\\u0982 \\u09ac\\u09bf\\u0995\\u09cd\\u09b0\\u09af\\u09bc \\u09aa\\u09b0\\u09bf\\u099a\\u09be\\u09b2\\u09a8\\u09be \\u0995\\u09b0\\u09c1\\u09a8\\u0964 \\u0986\\u099c\\u0987 \\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u09ac\\u09bf\\u09a8\\u09be\\u09ae\\u09c2\\u09b2\\u09cd\\u09af\\u09c7 \\u099f\\u09cd\\u09b0\\u09be\\u09af\\u09bc\\u09be\\u09b2 \\u09b6\\u09c1\\u09b0\\u09c1 \\u0995\\u09b0\\u09c1\\u09a8\\u0964\",\"meta_keywords\":\"\\u0987\\u09a8\\u09ad\\u09c7\\u09a8\\u09cd\\u099f\\u09b0\\u09bf \\u09ae\\u09cd\\u09af\\u09be\\u09a8\\u09c7\\u099c\\u09ae\\u09c7\\u09a8\\u09cd\\u099f, \\u09b8\\u09cd\\u099f\\u0995 \\u09ae\\u09cd\\u09af\\u09be\\u09a8\\u09c7\\u099c\\u09ae\\u09c7\\u09a8\\u09cd\\u099f, POS, \\u0997\\u09c1\\u09a6\\u09be\\u09ae, \\u09ae\\u09be\\u09b2\\u09cd\\u099f\\u09bf-\\u09b2\\u09cb\\u0995\\u09c7\\u09b6\\u09a8, SaaS\"},\"tr\":{\"meta_title\":\"Quantro \\u2014 Envanter ve Stok Y\\u00f6netim Platformu\",\"meta_description\":\"Tek bir g\\u00fc\\u00e7l\\u00fc platformdan envanter, depo, POS, sat\\u0131n alma ve sat\\u0131\\u015flar\\u0131 y\\u00f6netin. \\u00dccretsiz denemenizi bug\\u00fcn ba\\u015flat\\u0131n.\",\"meta_keywords\":\"envanter y\\u00f6netimi, stok y\\u00f6netimi, POS, depo, \\u00e7oklu lokasyon, SaaS\"},\"de\":{\"meta_title\":\"Quantro \\u2014 Inventar- und Bestandsverwaltungsplattform\",\"meta_description\":\"Verwalten Sie Inventar, Lager, POS, Eink\\u00e4ufe und Verk\\u00e4ufe \\u00fcber eine einzige leistungsstarke Plattform. Starten Sie noch heute Ihre kostenlose Testversion.\",\"meta_keywords\":\"Inventarverwaltung, Bestandsverwaltung, POS, Lager, Multi-Standort, SaaS\"},\"pt\":{\"meta_title\":\"Quantro \\u2014 Plataforma de gest\\u00e3o de invent\\u00e1rio e estoque\",\"meta_description\":\"Gerencie invent\\u00e1rio, armaz\\u00e9ns, PDV, compras e vendas em uma \\u00fanica plataforma poderosa. Comece seu teste gratuito hoje.\",\"meta_keywords\":\"gest\\u00e3o de invent\\u00e1rio, gest\\u00e3o de estoque, PDV, armaz\\u00e9m, multi-localiza\\u00e7\\u00e3o, SaaS\"}}', 'Stocky — Inventory & Stock Management Platform', 'Manage inventory, warehouses, POS, purchases, and sales from one powerful platform. Start your free trial today.', 'inventory management, stock management, POS, warehouse, multi-location, saas', NULL, 'images/super/settings/favicon.ico', '2026-07-07 00:14:15', '2026-07-07 00:14:15');

