INSERT INTO `landing_testimonials` (`id`, `translations`, `client_name`, `company_name`, `review`, `rating`, `avatar`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, '{\"fr\":{\"client_name\":\"Sarah Johnson\",\"company_name\":\"Urban Retail Co.\",\"review\":\"Stocky a transform\\u00e9 notre fa\\u00e7on de g\\u00e9rer l\'inventaire dans nos trois magasins. Les mises \\u00e0 jour de stock en temps r\\u00e9el nous ont sauv\\u00e9s des ruptures constantes.\"},\"ar\":{\"client_name\":\"\\u0633\\u0627\\u0631\\u0629 \\u062c\\u0648\\u0646\\u0633\\u0648\\u0646\",\"company_name\":\"\\u0623\\u0648\\u0631\\u0628\\u0627\\u0646 \\u0631\\u064a\\u062a\\u064a\\u0644\",\"review\":\"\\u063a\\u064a\\u0651\\u0631 Stocky \\u0637\\u0631\\u064a\\u0642\\u0629 \\u0625\\u062f\\u0627\\u0631\\u062a\\u0646\\u0627 \\u0644\\u0644\\u0645\\u062e\\u0632\\u0648\\u0646 \\u0639\\u0628\\u0631 \\u0645\\u062a\\u0627\\u062c\\u0631\\u0646\\u0627 \\u0627\\u0644\\u062b\\u0644\\u0627\\u062b\\u0629. \\u062a\\u062d\\u062f\\u064a\\u062b\\u0627\\u062a \\u0627\\u0644\\u0645\\u062e\\u0632\\u0648\\u0646 \\u0627\\u0644\\u0641\\u0648\\u0631\\u064a\\u0629 \\u0623\\u0646\\u0642\\u0630\\u062a\\u0646\\u0627 \\u0645\\u0646 \\u0646\\u0641\\u0627\\u062f \\u0627\\u0644\\u0645\\u062e\\u0632\\u0648\\u0646 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0645\\u0631.\"},\"es\":{\"client_name\":\"Sarah Johnson\",\"company_name\":\"Urban Retail Co.\",\"review\":\"Stocky transform\\u00f3 la forma en que gestionamos el inventario en nuestras tres tiendas. Las actualizaciones de stock en tiempo real nos salvaron de los desabastecimientos constantes.\"},\"hi\":{\"client_name\":\"\\u0938\\u093e\\u0930\\u093e \\u091c\\u0949\\u0928\\u0938\\u0928\",\"company_name\":\"\\u0905\\u0930\\u094d\\u092c\\u0928 \\u0930\\u093f\\u091f\\u0947\\u0932 \\u0915\\u0902\\u092a\\u0928\\u0940\",\"review\":\"Stocky \\u0928\\u0947 \\u0939\\u092e\\u093e\\u0930\\u0947 \\u0924\\u0940\\u0928 \\u0938\\u094d\\u091f\\u094b\\u0930 \\u092e\\u0947\\u0902 \\u0907\\u0928\\u094d\\u0935\\u0947\\u0902\\u091f\\u094d\\u0930\\u0940 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u0928 \\u0915\\u094b \\u092c\\u0926\\u0932 \\u0926\\u093f\\u092f\\u093e\\u0964 \\u0930\\u0940\\u092f\\u0932-\\u091f\\u093e\\u0907\\u092e \\u0938\\u094d\\u091f\\u0949\\u0915 \\u0905\\u092a\\u0921\\u0947\\u091f \\u0928\\u0947 \\u0939\\u092e\\u0947\\u0902 \\u0932\\u0917\\u093e\\u0924\\u093e\\u0930 \\u0938\\u094d\\u091f\\u0949\\u0915-\\u0906\\u0909\\u091f \\u0938\\u0947 \\u092c\\u091a\\u093e\\u092f\\u093e\\u0964\"},\"bn\":{\"client_name\":\"\\u09b8\\u09be\\u09b0\\u09be \\u099c\\u09a8\\u09b8\\u09a8\",\"company_name\":\"\\u0986\\u09b0\\u09cd\\u09ac\\u09be\\u09a8 \\u09b0\\u09bf\\u099f\\u09c7\\u0987\\u09b2 \\u0995\\u09cb.\",\"review\":\"Stocky \\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u09a4\\u09bf\\u09a8\\u099f\\u09bf \\u09a6\\u09cb\\u0995\\u09be\\u09a8\\u09c7 \\u0987\\u09a8\\u09ad\\u09c7\\u09a8\\u09cd\\u099f\\u09b0\\u09bf \\u09aa\\u09b0\\u09bf\\u099a\\u09be\\u09b2\\u09a8\\u09be\\u09b0 \\u09a7\\u09b0\\u09a8 \\u09aa\\u09b0\\u09bf\\u09ac\\u09b0\\u09cd\\u09a4\\u09a8 \\u0995\\u09b0\\u09c7\\u099b\\u09c7\\u0964 \\u09b0\\u09bf\\u09af\\u09bc\\u09c7\\u09b2-\\u099f\\u09be\\u0987\\u09ae \\u09b8\\u09cd\\u099f\\u0995 \\u0986\\u09aa\\u09a1\\u09c7\\u099f \\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u0995\\u09cd\\u09b0\\u09ae\\u09be\\u0997\\u09a4 \\u09b8\\u09cd\\u099f\\u0995-\\u0986\\u0989\\u099f \\u09a5\\u09c7\\u0995\\u09c7 \\u09ac\\u09be\\u0981\\u099a\\u09bf\\u09af\\u09bc\\u09c7\\u099b\\u09c7\\u0964\"},\"tr\":{\"client_name\":\"Sarah Johnson\",\"company_name\":\"Urban Retail Co.\",\"review\":\"Stocky, \\u00fc\\u00e7 ma\\u011fazam\\u0131zdaki envanter y\\u00f6netim \\u015feklimizi d\\u00f6n\\u00fc\\u015ft\\u00fcrd\\u00fc. Ger\\u00e7ek zamanl\\u0131 stok g\\u00fcncellemeleri bizi s\\u00fcrekli stok t\\u00fckenmesinden kurtard\\u0131.\"},\"de\":{\"client_name\":\"Sarah Johnson\",\"company_name\":\"Urban Retail Co.\",\"review\":\"Stocky hat die Art und Weise ver\\u00e4ndert, wie wir das Inventar in unseren drei Gesch\\u00e4ften verwalten. Echtzeit-Bestandsaktualisierungen haben uns vor st\\u00e4ndigen Engp\\u00e4ssen bewahrt.\"},\"pt\":{\"client_name\":\"Sarah Johnson\",\"company_name\":\"Urban Retail Co.\",\"review\":\"O Stocky transformou a forma como gerenciamos o invent\\u00e1rio em nossas tr\\u00eas lojas. Atualiza\\u00e7\\u00f5es de estoque em tempo real nos salvaram de rupturas constantes.\"}}', 'Sarah Johnson', 'Urban Retail Co.', 'Stocky transformed how we manage inventory across our three stores. Real-time stock updates saved us from constant stock-outs.', 5, NULL, 1, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15'),
(2, '{\"fr\":{\"client_name\":\"Ahmed Benali\",\"company_name\":\"MedSupply Direct\",\"review\":\"La fonctionnalit\\u00e9 multi-entrep\\u00f4t est r\\u00e9volutionnaire. Nous avons r\\u00e9duit les erreurs de transfert de 80% d\\u00e8s le premier mois.\"},\"ar\":{\"client_name\":\"\\u0623\\u062d\\u0645\\u062f \\u0628\\u0646 \\u0639\\u0644\\u064a\",\"company_name\":\"\\u0645\\u064a\\u062f\\u0633\\u0628\\u0644\\u0627\\u064a \\u062f\\u0627\\u064a\\u0631\\u0643\\u062a\",\"review\":\"\\u0645\\u064a\\u0632\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0648\\u062f\\u0639\\u0627\\u062a \\u0627\\u0644\\u0645\\u062a\\u0639\\u062f\\u062f\\u0629 \\u063a\\u064a\\u0651\\u0631\\u062a \\u0642\\u0648\\u0627\\u0639\\u062f \\u0627\\u0644\\u0644\\u0639\\u0628\\u0629. \\u0642\\u0644\\u0644\\u0646\\u0627 \\u0623\\u062e\\u0637\\u0627\\u0621 \\u0627\\u0644\\u0646\\u0642\\u0644 \\u0628\\u0646\\u0633\\u0628\\u0629 80% \\u0641\\u064a \\u0627\\u0644\\u0634\\u0647\\u0631 \\u0627\\u0644\\u0623\\u0648\\u0644.\"},\"es\":{\"client_name\":\"Ahmed Benali\",\"company_name\":\"MedSupply Direct\",\"review\":\"La funci\\u00f3n multi-almac\\u00e9n es un cambio radical. Redujimos los errores de transferencia en un 80% en el primer mes.\"},\"hi\":{\"client_name\":\"\\u0905\\u0939\\u092e\\u0926 \\u092c\\u0947\\u0928\\u093e\\u0932\\u0940\",\"company_name\":\"\\u092e\\u0947\\u0921\\u0938\\u092a\\u094d\\u0932\\u093e\\u0908 \\u0921\\u093e\\u092f\\u0930\\u0947\\u0915\\u094d\\u091f\",\"review\":\"\\u092e\\u0932\\u094d\\u091f\\u0940-\\u0935\\u0947\\u092f\\u0930\\u0939\\u093e\\u0909\\u0938 \\u092b\\u0940\\u091a\\u0930 \\u0928\\u0947 \\u0938\\u092c \\u0915\\u0941\\u091b \\u092c\\u0926\\u0932 \\u0926\\u093f\\u092f\\u093e\\u0964 \\u0939\\u092e\\u0928\\u0947 \\u092a\\u0939\\u0932\\u0947 \\u092e\\u0939\\u0940\\u0928\\u0947 \\u092e\\u0947\\u0902 \\u091f\\u094d\\u0930\\u093e\\u0902\\u0938\\u092b\\u0930 \\u0924\\u094d\\u0930\\u0941\\u091f\\u093f\\u092f\\u094b\\u0902 \\u0915\\u094b 80% \\u0915\\u092e \\u0915\\u0930 \\u0926\\u093f\\u092f\\u093e\\u0964\"},\"bn\":{\"client_name\":\"\\u0986\\u09b9\\u09ae\\u09c7\\u09a6 \\u09ac\\u09c7\\u09a8\\u09be\\u09b2\\u09bf\",\"company_name\":\"\\u09ae\\u09c7\\u09a1\\u09b8\\u09be\\u09aa\\u09cd\\u09b2\\u09be\\u0987 \\u09a1\\u09bf\\u09b0\\u09c7\\u0995\\u09cd\\u099f\",\"review\":\"\\u09ae\\u09be\\u09b2\\u09cd\\u099f\\u09bf-\\u0997\\u09c1\\u09a6\\u09be\\u09ae \\u09ab\\u09bf\\u099a\\u09be\\u09b0\\u099f\\u09bf \\u0997\\u09c7\\u09ae-\\u099a\\u09c7\\u099e\\u09cd\\u099c\\u09be\\u09b0\\u0964 \\u0986\\u09ae\\u09b0\\u09be \\u09aa\\u09cd\\u09b0\\u09a5\\u09ae \\u09ae\\u09be\\u09b8\\u09c7\\u0987 \\u099f\\u09cd\\u09b0\\u09be\\u09a8\\u09cd\\u09b8\\u09ab\\u09be\\u09b0 \\u09a4\\u09cd\\u09b0\\u09c1\\u099f\\u09bf 80% \\u0995\\u09ae\\u09bf\\u09af\\u09bc\\u09c7 \\u098f\\u09a8\\u09c7\\u099b\\u09bf\\u0964\"},\"tr\":{\"client_name\":\"Ahmed Benali\",\"company_name\":\"MedSupply Direct\",\"review\":\"\\u00c7oklu depo \\u00f6zelli\\u011fi oyunun kurallar\\u0131n\\u0131 de\\u011fi\\u015ftirdi. \\u0130lk ayda transfer hatalar\\u0131n\\u0131 %80 azaltt\\u0131k.\"},\"de\":{\"client_name\":\"Ahmed Benali\",\"company_name\":\"MedSupply Direct\",\"review\":\"Die Multi-Lager-Funktion ist bahnbrechend. Wir haben Transferfehler im ersten Monat um 80% reduziert.\"},\"pt\":{\"client_name\":\"Ahmed Benali\",\"company_name\":\"MedSupply Direct\",\"review\":\"O recurso multi-armaz\\u00e9m \\u00e9 revolucion\\u00e1rio. Reduzimos erros de transfer\\u00eancia em 80% no primeiro m\\u00eas.\"}}', 'Ahmed Benali', 'MedSupply Direct', 'The multi-warehouse feature is a game-changer. We reduced transfer errors by 80% in the first month.', 5, NULL, 2, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15'),
(3, '{\"fr\":{\"client_name\":\"Maria Chen\",\"company_name\":\"FreshMart Grocery\",\"review\":\"Facile \\u00e0 configurer et le POS fonctionne parfaitement. Nos caissiers \\u00e9taient \\u00e0 l\'aise d\\u00e8s le premier jour.\"},\"ar\":{\"client_name\":\"\\u0645\\u0627\\u0631\\u064a\\u0627 \\u062a\\u0634\\u064a\\u0646\",\"company_name\":\"\\u0641\\u0631\\u064a\\u0634 \\u0645\\u0627\\u0631\\u062a\",\"review\":\"\\u0633\\u0647\\u0644 \\u0627\\u0644\\u0625\\u0639\\u062f\\u0627\\u062f \\u0648\\u0646\\u0642\\u0627\\u0637 \\u0627\\u0644\\u0628\\u064a\\u0639 \\u062a\\u0639\\u0645\\u0644 \\u0628\\u0633\\u0644\\u0627\\u0633\\u0629. \\u0643\\u0627\\u0646 \\u0645\\u0648\\u0638\\u0641\\u0648 \\u0627\\u0644\\u0643\\u0627\\u0634\\u064a\\u0631 \\u0645\\u0631\\u062a\\u0627\\u062d\\u064a\\u0646 \\u0645\\u0639\\u0647 \\u0645\\u0646 \\u0627\\u0644\\u064a\\u0648\\u0645 \\u0627\\u0644\\u0623\\u0648\\u0644.\"},\"es\":{\"client_name\":\"Maria Chen\",\"company_name\":\"FreshMart Grocery\",\"review\":\"F\\u00e1cil de configurar y el POS funciona a la perfecci\\u00f3n. Nuestros cajeros se sintieron c\\u00f3modos desde el primer d\\u00eda.\"},\"hi\":{\"client_name\":\"\\u092e\\u093e\\u0930\\u093f\\u092f\\u093e \\u091a\\u0947\\u0928\",\"company_name\":\"\\u092b\\u094d\\u0930\\u0947\\u0936\\u092e\\u093e\\u0930\\u094d\\u091f \\u0917\\u094d\\u0930\\u0949\\u0938\\u0930\\u0940\",\"review\":\"\\u0938\\u0947\\u091f\\u0905\\u092a \\u0915\\u0930\\u0928\\u093e \\u0906\\u0938\\u093e\\u0928 \\u0914\\u0930 POS \\u092c\\u093f\\u0932\\u094d\\u0915\\u0941\\u0932 \\u0938\\u0939\\u0940 \\u0915\\u093e\\u092e \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0939\\u092e\\u093e\\u0930\\u0947 \\u0915\\u0948\\u0936\\u093f\\u092f\\u0930 \\u092a\\u0939\\u0932\\u0947 \\u0926\\u093f\\u0928 \\u0938\\u0947 \\u0939\\u0940 \\u0938\\u0939\\u091c \\u0925\\u0947\\u0964\"},\"bn\":{\"client_name\":\"\\u09ae\\u09be\\u09b0\\u09bf\\u09af\\u09bc\\u09be \\u099a\\u09c7\\u09a8\",\"company_name\":\"\\u09ab\\u09cd\\u09b0\\u09c7\\u09b6\\u09ae\\u09be\\u09b0\\u09cd\\u099f \\u0997\\u09cd\\u09b0\\u09cb\\u09b8\\u09be\\u09b0\\u09bf\",\"review\":\"\\u09b8\\u09c7\\u099f\\u0986\\u09aa \\u0995\\u09b0\\u09be \\u09b8\\u09b9\\u099c \\u098f\\u09ac\\u0982 POS \\u09a8\\u09bf\\u0996\\u09c1\\u0981\\u09a4\\u09ad\\u09be\\u09ac\\u09c7 \\u0995\\u09be\\u099c \\u0995\\u09b0\\u09c7\\u0964 \\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u0995\\u09cd\\u09af\\u09be\\u09b6\\u09bf\\u09af\\u09bc\\u09be\\u09b0\\u09b0\\u09be \\u09aa\\u09cd\\u09b0\\u09a5\\u09ae \\u09a6\\u09bf\\u09a8 \\u09a5\\u09c7\\u0995\\u09c7\\u0987 \\u09b8\\u09cd\\u09ac\\u09be\\u099a\\u09cd\\u099b\\u09a8\\u09cd\\u09a6\\u09cd\\u09af \\u09ac\\u09cb\\u09a7 \\u0995\\u09b0\\u09c7\\u099b\\u09c7\\u0964\"},\"tr\":{\"client_name\":\"Maria Chen\",\"company_name\":\"FreshMart Grocery\",\"review\":\"Kurulumu kolay ve POS kusursuz \\u00e7al\\u0131\\u015f\\u0131yor. Kasiyerlerimiz ilk g\\u00fcnden rahat etti.\"},\"de\":{\"client_name\":\"Maria Chen\",\"company_name\":\"FreshMart Grocery\",\"review\":\"Einfach einzurichten und das POS funktioniert einwandfrei. Unsere Kassierer waren vom ersten Tag an damit vertraut.\"},\"pt\":{\"client_name\":\"Maria Chen\",\"company_name\":\"FreshMart Grocery\",\"review\":\"F\\u00e1cil de configurar e o PDV funciona perfeitamente. Nossos caixas se sentiram confort\\u00e1veis desde o primeiro dia.\"}}', 'Maria Chen', 'FreshMart Grocery', 'Easy to set up and the POS works flawlessly. Our cashiers were comfortable with it from day one.', 4, NULL, 3, 1, '2026-07-07 00:14:15', '2026-07-07 00:14:15');

